import json
import urllib.request
import urllib.error
import ssl

def fetch_neotoma_collection(self, **kwargs):
    """
    Fetch collection-level metadata from the Neotoma Paleoecology Database.

    This function uses the Neotoma API v2.0 to retrieve metadata about
    constituent databases (collections) within Neotoma. It supports:
    - Listing all constituent databases (collections)
    - Looking up a specific constituent database by shortname
    - Looking up dataset metadata by DOI

    Parameters available via kwargs:
    - dataset_shortname: The name of a constituent database (e.g., "FAUNMAP", "European Pollen Database")
    - doi: A dataset DOI to look up specific dataset metadata
    - uuid: A databaseid (integer) for a specific constituent database
    """
    base_url = "https://api.neotomadb.org/v2.0"

    shortname = kwargs.get('dataset_shortname')
    doi = kwargs.get('doi')
    db_id = kwargs.get('uuid') or kwargs.get('official_website_id')

    # Strategy 1: If DOI is provided, use the datasets endpoint
    if doi:
        url = f"{base_url}/data/datasets?doi={doi}"
        try:
            result = self._get_with_retry(url)
            data = json.loads(result) if isinstance(result, str) else result
            if data.get('status') == 'success' and data.get('data'):
                return {"source": "Neotoma-Custom", "data": data}
            else:
                return {"error": f"DOI not found in Neotoma: {doi}"}
        except Exception as e:
            return {"error": f"Failed to fetch dataset by DOI: {str(e)}"}

    # Strategy 2: If a specific database ID is provided, look it up
    if db_id:
        url = f"{base_url}/data/dbtables/constituentdatabases"
        try:
            result = self._get_with_retry(url)
            data = json.loads(result) if isinstance(result, str) else result
            if data.get('status') == 'success' and data.get('data'):
                for db in data['data']:
                    if str(db.get('databaseid')) == str(db_id):
                        return {"source": "Neotoma-Custom", "data": {"status": "success", "data": [db]}}
                return {"error": f"Constituent database with ID {db_id} not found"}
            return {"error": "Failed to fetch constituent databases"}
        except Exception as e:
            return {"error": f"Failed to fetch constituent databases: {str(e)}"}

    # Strategy 3: Fetch all constituent databases, optionally filter by shortname
    url = f"{base_url}/data/dbtables/constituentdatabases"
    try:
        result = self._get_with_retry(url)
        data = json.loads(result) if isinstance(result, str) else result

        if data.get('status') != 'success':
            return {"error": "Neotoma API returned non-success status"}

        databases = data.get('data', [])

        if shortname:
            # Filter by name (case-insensitive partial match)
            matched = [
                db for db in databases
                if shortname.lower() in (db.get('databasename') or '').lower()
            ]
            if matched:
                return {"source": "Neotoma-Custom", "data": {"status": "success", "data": matched}}
            else:
                return {"error": f"Constituent database '{shortname}' not found"}

        # Return all constituent databases (collection-level metadata)
        return {"source": "Neotoma-Custom", "data": data}

    except Exception as e:
        return {"error": f"Failed to fetch constituent databases: {str(e)}"}


# Test code below
class MockSelf:
    @staticmethod
    def _get_with_retry(url, headers=None):
        """Simple HTTP GET with retry logic."""
        ctx = ssl.create_default_context()
        req = urllib.request.Request(url)
        if headers:
            for k, v in headers.items():
                req.add_header(k, v)
        req.add_header('User-Agent', 'NeotomaMetadataFetcher/1.0')

        for attempt in range(3):
            try:
                with urllib.request.urlopen(req, context=ctx, timeout=30) as resp:
                    return resp.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code in (429, 503):
                    import time
                    time.sleep(2 ** attempt)
                    continue
                raise
            except Exception:
                if attempt == 2:
                    raise
                import time
                time.sleep(2 ** attempt)
        raise Exception("Max retries exceeded")


mock_self = MockSelf()

# Test 1: Fetch all constituent databases (collection-level metadata)
print("=== Test 1: All constituent databases ===")
result = fetch_neotoma_collection(mock_self)
if 'error' not in result:
    dbs = result['data'].get('data', [])
    print(f"Found {len(dbs)} constituent databases")
    for db in dbs[:3]:
        print(f"  - [{db['databaseid']}] {db['databasename']}")
    if len(dbs) > 3:
        print(f"  ... and {len(dbs)-3} more")
else:
    print(f"ERROR: {result['error']}")

# Test 2: Fetch by shortname
print("\n=== Test 2: Filter by shortname 'FAUNMAP' ===")
result = fetch_neotoma_collection(mock_self, dataset_shortname='FAUNMAP')
if 'error' not in result:
    dbs = result['data'].get('data', [])
    print(f"Found {len(dbs)} matching databases:")
    for db in dbs:
        print(f"  - [{db['databaseid']}] {db['databasename']} | contactid={db['contactid']} | description={db.get('description')}")
else:
    print(f"ERROR: {result['error']}")

# Test 3: Fetch by DOI
print("\n=== Test 3: Fetch by DOI '10.21233/9twd-s570' ===")
result = fetch_neotoma_collection(mock_self, doi='10.21233/9twd-s570')
if 'error' not in result:
    site_data = result['data'].get('data', [{}])[0] if result['data'].get('data') else {}
    site = site_data.get('site', {})
    datasets = site.get('datasets', [])
    print(f"Site: {site.get('sitename')} (ID: {site.get('siteid')})")
    print(f"Description: {site.get('sitedescription')}")
    print(f"Location: {site.get('geography')}")
    if datasets:
        ds = datasets[0]
        print(f"Dataset DOIs: {ds.get('doi')}")
        print(f"Database: {ds.get('database')}")
        print(f"Dataset Type: {ds.get('datasettype')}")
else:
    print(f"ERROR: {result['error']}")

# Test 4: Fetch by database ID
print("\n=== Test 4: Fetch by database ID '1' ===")
result = fetch_neotoma_collection(mock_self, uuid='1')
if 'error' not in result:
    dbs = result['data'].get('data', [])
    for db in dbs:
        print(f"  - [{db['databaseid']}] {db['databasename']} | contactid={db['contactid']}")
else:
    print(f"ERROR: {result['error']}")

print("\n=== All tests completed ===")

import json

def fetch_neotoma_collection(self, **kwargs):
    """
    Fetch collection-level metadata from the Neotoma Paleoecology Database.

    Uses the Neotoma API v2.0 to retrieve:
    - All constituent databases (collections) via /v2.0/data/dbtables/constituentdatabases
    - Dataset-level metadata by DOI via /v2.0/data/datasets?doi=...
    - Filtering by dataset_shortname (constituent database name like "FAUNMAP")

    Parameters available via kwargs:
    - dataset_shortname: Constituent database name (e.g., "FAUNMAP")
    - doi: A dataset DOI
    - uuid / official_website_id: A databaseid (integer)
    """
    base_url = "https://api.neotomadb.org/v2.0"

    shortname = kwargs.get('dataset_shortname')
    doi = kwargs.get('doi')
    db_id = kwargs.get('uuid') or kwargs.get('official_website_id')

    def parse_response(resp):
        """Handle response from _get_with_retry - may be str, bytes, Response object, or dict."""
        # If it's already a dict, return it
        if isinstance(resp, dict):
            return resp
        # If it has a .json() method (requests.Response)
        if hasattr(resp, 'json'):
            return resp.json()
        # If it has a .text attribute
        if hasattr(resp, 'text'):
            return json.loads(resp.text)
        # If it's bytes
        if isinstance(resp, bytes):
            return json.loads(resp.decode('utf-8'))
        # If it's a string
        if isinstance(resp, str):
            return json.loads(resp)
        raise TypeError(f"Unexpected response type: {type(resp)}")

    try:
        # Strategy 1: DOI lookup -> dataset metadata
        if doi:
            url = f"{base_url}/data/datasets?doi={doi}"
            result = self._get_with_retry(url)
            data = parse_response(result)
            if data.get('status') == 'success' and data.get('data'):
                return {"source": "Neotoma-Custom", "data": data}
            return {"error": f"DOI not found in Neotoma: {doi}"}

        # Strategy 2 & 3: Constituent databases
        url = f"{base_url}/data/dbtables/constituentdatabases"
        result = self._get_with_retry(url)
        data = parse_response(result)

        if data.get('status') != 'success':
            return {"error": "Neotoma API returned non-success status"}

        databases = data.get('data', [])

        # Filter by ID if provided
        if db_id:
            matched = [db for db in databases if str(db.get('databaseid')) == str(db_id)]
            if matched:
                return {"source": "Neotoma-Custom", "data": {"status": "success", "data": matched}}
            return {"error": f"Constituent database with ID '{db_id}' not found"}

        # Filter by shortname if provided
        if shortname:
            matched = [
                db for db in databases
                if shortname.lower() in (db.get('databasename') or '').lower()
            ]
            if matched:
                return {"source": "Neotoma-Custom", "data": {"status": "success", "data": matched}}
            return {"error": f"Constituent database '{shortname}' not found"}

        # Return all
        return {"source": "Neotoma-Custom", "data": data}

    except Exception as e:
        return {"error": f"Failed: {str(e)}"}

