        # Step 1: Search for the article by DOI
        search_url = f"{BASE}/articles/search"
        search_payload = {"resource_doi": doi}
        try:
            # Use requests.post directly since _get_with_retry is GET-only
            import requests as req
            search_resp = req.post(
                search_url, 
                json=search_payload, 
                headers=custom_headers,
                timeout=30
            )
            search_resp.raise_for_status()
            results = search_resp.json()

            if not results:
                return {"error": f"No figshare article found for DOI: {doi}"}

            # Step 2: Get the first matching article's full metadata
            article_id = results[0].get("id")
            if not article_id:
                return {"error": "Search result missing article ID"}

            url = f"{BASE}/articles/{article_id}"
            data = self._get_with_retry(url, headers=custom_headers)
            return {"source": "figshare-Custom", "data": data}

        except Exception as e:
            return {"error": f"Figshare DOI lookup failed: {str(e)}"}

